API Gateway / BFF.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway / BFF container

Container_Boundary(api_gateway_bff, "API Gateway / BFF") {
    Component(Regional_Edge_Router_Policy_Enforcer, "Regional Edge Router & Policy Enforcer", "Envoy with Wasm filters", "Provides native edge routing, TLS termination, and low-latency policy enforcement without extra network hops.")
    Component(BFF_Orchestration_Layer, "BFF Orchestration Layer", "Node.js", "Powers the BFF Orchestration Layer for dynamic response aggregation and payload shaping.")
}

Rel(Regional_Edge_Router_Policy_Enforcer, BFF_Orchestration_Layer, "Forwards authorized geo-compliant traffic", "HTTP/2")

@enduml

Video Consultation Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(video_consultation_service, "Video Consultation Service") {
    Component(SignalingComponent, "Signaling Component", "Node.js / WebSockets", "Manages real-time WebRTC signaling for video consultations.")
    Component(SFUMediaRouter, "SFU Media Router", "MediaSoup / C++ / Node.js", "Handles adaptive bitrate video routing for unstable and low-bandwidth connections.")
    Component(SessionManagementController, "Session Management Controller", "Node.js / Express", "Manages consultation session logic and lifecycle.")
    Component(AuditMetadataLoggerComponent, "Audit & Metadata Logger Component", "Node.js", "Emits and persists compliance audit logs and session metadata.")
}

Rel(SignalingComponent, SFUMediaRouter, "Manages RTP/RTCP media routing", "Internal UDP/TCP")
Rel(SFUMediaRouter, SignalingComponent, "Manages RTP/RTCP media routing", "Internal UDP/TCP")
Rel(SessionManagementController, AuditMetadataLoggerComponent, "Emits session lifecycle events", "Internal gRPC")
@enduml

AI Symptom Checker Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(ai_symptom_checker_service, "AI Symptom Checker Service") {
    Component(Triage_Orchestrator, "Triage Orchestrator", "Python / FastAPI", "Internal component that orchestrates symptom analysis requests and dispatches payload snapshots.")
    Component(Inference_Adapter, "Inference Adapter", "Python / LangChain / PyTorch", "Calculates urgency using AI models and inference runtime.")
    Component(Audit_Traceability_Logger, "Audit & Traceability Logger", "Python Component", "Dispatches payload snapshots and writes immutable records for compliance.")
    Component(Compliance_Exporter, "Compliance Exporter", "Python Background Worker", "Aggregates logs for compliance reports to ensure EU MDR traceability.")
}

Rel(Triage_Orchestrator, Inference_Adapter, "Requests urgency calculation", "In-process async / gRPC")
Rel(Triage_Orchestrator, Audit_Traceability_Logger, "Dispatches payload snapshots", "Cloud Pub/Sub Lite")

@enduml

Consent & Identity Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(consent_identity_service, "Consent & Identity Service") {
    Component(AuthComponent, "Auth Component", "Keycloak", "Handles OIDC/OAuth2 authentication and user federation.")
    Component(ConsentEnforcementComponent, "Consent Enforcement Component", "Java / Spring Boot", "Evaluates real-time purpose-based access policies and persists purpose-based consent ledgers.")
